# parse html into pandas dataframe

import pandas as pd
from bs4 import BeautifulSoup
from datetime import datetime
import re

def parse_congress_trading_html(html_content):
    """
    Parse HTML content containing congressional trading data and return a pandas DataFrame.
    
    Args:
        html_content (str): HTML content as string
    
    Returns:
        pd.DataFrame: DataFrame with columns: representative, type_of_trade, amount, transaction_date
    """
    soup = BeautifulSoup(html_content, 'html.parser')
    
    data = []
    
    # Find all table rows
    rows = soup.find_all('tr')
    
    for row in rows:
        # Find all table data cells in this row
        cells = row.find_all('td')
        
        if len(cells) >= 5:  # Ensure we have enough cells
            try:
                # Extract representative name (from 3rd cell)
                rep_cell = cells[2]
                rep_name = rep_cell.find('span').get_text(strip=True)
                
                # Extract trade type (buy/sell) from 2nd cell
                trade_cell = cells[1]
                trade_type_span = trade_cell.find('span', class_='positive')
                if trade_type_span:
                    trade_type = trade_type_span.get_text(strip=True)
                    # Convert to simpler format
                    if 'Purchase' in trade_type:
                        trade_type = 'Buy'
                    elif 'Sale' in trade_type:
                        trade_type = 'Sell'
                
                # Extract amount from 2nd cell (second span)
                amount_span = trade_cell.find_all('span')[1]
                amount = amount_span.get_text(strip=True)
                
                # Extract transaction date from 4th cell
                date_cell = cells[3]
                transaction_date = date_cell.get_text(strip=True)
                
                # Append to data list
                data.append({
                    'representative': rep_name,
                    'type_of_trade': trade_type,
                    'amount': amount,
                    'transaction_date': transaction_date
                })
                
            except (AttributeError, IndexError) as e:
                # Skip rows that don't match the expected structure
                continue
    
    # Create DataFrame
    df = pd.DataFrame(data)
    return df

def parse_date_to_format_robust(date_string):
    """
    More robust date parser that handles various formats and validates the output.
    """
    # Common month abbreviations mapping
    month_map = {
        'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
        'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12
    }
    
    try:
        # Remove extra whitespace
        date_string = ' '.join(date_string.split())
        
        # Try to parse using datetime first
        try:
            date_obj = datetime.strptime(date_string, '%b %d, %Y')
        except ValueError:
            # Try alternative format if the first one fails
            try:
                date_obj = datetime.strptime(date_string, '%B %d, %Y')
            except ValueError:
                # Manual parsing as fallback
                parts = date_string.split()
                if len(parts) >= 3:
                    month_str = parts[0]
                    day_str = parts[1].rstrip(',')
                    year_str = parts[2]
                    
                    month = month_map.get(month_str[:3])
                    day = int(day_str)
                    year = int(year_str)
                    
                    date_obj = datetime(year, month, day)
                else:
                    raise ValueError(f"Unexpected date format: {date_string}")
        
        # Format to the required string format
        formatted_date = date_obj.strftime('%Y-%m-%d 00:00:00-05:00')
        
        return formatted_date
        
    except Exception as e:
        print(f"Error parsing date '{date_string}': {e}")
        return date_string  # Return original if parsing fails

